import { useState, useEffect } from "react";

const SUPA_URL = "https://rgsgjqnlvyossuykemjl.supabase.co";
const SUPA_KEY = "sb_publishable_uC6SF60PfuFnZfDDLRo2Wg_m7l2FoBW";
const LOGO    = "data:image/png;base64,";

const t = {
  bg:"#f5f7f0", card:"#ffffff", bord:"#dde8d0",
  green:"#4a7c3f", greenLight:"#6aab5e", greenDark:"#2d5a24",
  gold:"#e8b84b", text:"#2d3a2e", muted:"#6b7c6b",
  red:"#dc2626", blue:"#1d4ed8",
};

async function signIn(email, password) {
  const res = await fetch(`${SUPA_URL}/auth/v1/token?grant_type=password`, {
    method:"POST",
    headers:{"apikey":SUPA_KEY,"Content-Type":"application/json"},
    body:JSON.stringify({email,password}),
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.error_description || data.msg || "Erro ao entrar");
  localStorage.setItem("dl_session", JSON.stringify(data));
  return data;
}

function signOut() {
  localStorage.removeItem("dl_session");
  window.location.reload();
}

function getSession() {
  try {
    const s = localStorage.getItem("dl_session");
    if (!s) return null;
    const sess = JSON.parse(s);
    if (sess.expires_at && Date.now() > sess.expires_at * 1000) {
      localStorage.removeItem("dl_session");
      return null;
    }
    return sess;
  } catch { return null; }
}

async function getPerfil(userId, token) {
  try {
    const res = await fetch(`${SUPA_URL}/rest/v1/perfis?id=eq.${userId}&select=*`, {
      headers:{"apikey":SUPA_KEY,"Authorization":`Bearer ${token}`},
    });
    const data = await res.json();
    return data[0] || null;
  } catch { return null; }
}

export default function App() {
  const [session,  setSession]  = useState(null);
  const [perfil,   setPerfil]   = useState(null);
  const [loading,  setLoading]  = useState(true);
  const [email,    setEmail]    = useState("");
  const [senha,    setSenha]    = useState("");
  const [erro,     setErro]     = useState(null);
  const [entrando, setEntrando] = useState(false);
  const [verSenha, setVerSenha] = useState(false);

  useEffect(() => {
    (async () => {
      try {
        const sess = getSession();
        if (sess) {
          setSession(sess);
          const p = await getPerfil(sess.user.id, sess.access_token);
          setPerfil(p);
        }
      } catch(e) { console.error(e); }
      finally { setLoading(false); }
    })();
  }, []);

  const handleLogin = async () => {
    if (!email || !senha) { setErro("Preencha e-mail e senha."); return; }
    setEntrando(true); setErro(null);
    try {
      const sess = await signIn(email, senha);
      setSession(sess);
      const p = await getPerfil(sess.user.id, sess.access_token);
      setPerfil(p);
    } catch(e) {
      setErro(e.message === "Invalid login credentials" ? "E-mail ou senha incorretos." : e.message);
    } finally { setEntrando(false); }
  };

  const css = `
    @keyframes spin { to { transform: rotate(360deg) } }
    @keyframes fadeIn { from { opacity:0; transform:translateY(12px) } to { opacity:1; transform:translateY(0) } }
    * { box-sizing: border-box; }
    input:focus { outline: none; border-color: #4a7c3f !important; box-shadow: 0 0 0 3px rgba(74,124,63,0.15); }
  `;

  if (loading) return (
    <div style={{ minHeight:"100vh", background:`linear-gradient(135deg,${t.greenDark},${t.green},${t.greenLight})`, display:"flex", alignItems:"center", justifyContent:"center" }}>
      <style>{css}</style>
      <div style={{ textAlign:"center" }}>
        <img src={LOGO} style={{ width:120, marginBottom:24, filter:"drop-shadow(0 4px 12px rgba(0,0,0,0.3))" }} alt="" />
        <div style={{ width:32,height:32,border:"3px solid rgba(255,255,255,0.3)",borderTop:"3px solid #fff",borderRadius:"50%",animation:"spin 0.8s linear infinite",margin:"0 auto" }} />
      </div>
    </div>
  );

  // ── LOGADO ──
  if (session) {
    const nome  = perfil?.nome || session.user?.email || "Usuário";
    const nivel = perfil?.nivel || "colaborador";
    return (
      <div style={{ minHeight:"100vh", background:`linear-gradient(135deg,${t.greenDark},${t.green},${t.greenLight})`, display:"flex", alignItems:"center", justifyContent:"center", fontFamily:"system-ui,sans-serif", padding:16 }}>
        <style>{css}</style>
        <div style={{ background:"#fff", borderRadius:24, padding:"40px 32px", maxWidth:400, width:"100%", textAlign:"center", boxShadow:"0 20px 60px rgba(0,0,0,0.2)", animation:"fadeIn 0.4s ease" }}>
          <img src={LOGO} style={{ width:150, display:"block", margin:"0 auto 20px" }} alt="" />

          <div style={{ width:64,height:64,borderRadius:"50%",background:`linear-gradient(135deg,${t.green},${t.greenLight})`,display:"flex",alignItems:"center",justifyContent:"center",color:"#fff",fontSize:26,fontWeight:800,margin:"0 auto 12px" }}>
            {nome[0]?.toUpperCase()}
          </div>

          <div style={{ color:t.text, fontSize:19, fontWeight:700, marginBottom:4 }}>Olá, {nome.split(" ")[0]}! 👋</div>
          <div style={{ color:t.muted, fontSize:13, marginBottom:16 }}>{session.user?.email}</div>

          <div style={{ display:"inline-flex", alignItems:"center", gap:8, background:nivel==="admin"?"#fefce8":"#f0fdf4", border:`1px solid ${nivel==="admin"?t.gold:t.greenLight}`, borderRadius:10, padding:"8px 16px", marginBottom:20 }}>
            <span style={{ fontSize:16 }}>{nivel==="admin"?"👑":"👤"}</span>
            <span style={{ color:nivel==="admin"?"#92400e":t.greenDark, fontSize:14, fontWeight:700 }}>
              {nivel==="admin"?"Administradora":"Colaboradora"}
            </span>
          </div>

          <div style={{ background:"#f0fdf4", border:"1px solid #bbf7d0", borderRadius:12, padding:"14px 16px", marginBottom:24 }}>
            <div style={{ color:t.greenDark, fontSize:14, fontWeight:700, marginBottom:4 }}>✅ Login funcionando!</div>
            <div style={{ color:t.muted, fontSize:13 }}>Sistema pronto para uso.</div>
          </div>

          <button onClick={signOut} style={{ background:"transparent", color:t.red, border:`1.5px solid ${t.red}`, borderRadius:10, padding:"10px 24px", cursor:"pointer", fontSize:14, fontWeight:700 }}>
            🚪 Sair
          </button>
        </div>
      </div>
    );
  }

  // ── TELA DE LOGIN ──
  return (
    <div style={{ minHeight:"100vh", background:`linear-gradient(135deg,${t.greenDark},${t.green},${t.greenLight})`, display:"flex", alignItems:"center", justifyContent:"center", fontFamily:"system-ui,sans-serif", padding:16 }}>
      <style>{css}</style>

      <div style={{ background:"#fff", borderRadius:28, padding:"44px 32px", maxWidth:380, width:"100%", textAlign:"center", boxShadow:"0 20px 60px rgba(0,0,0,0.25)", animation:"fadeIn 0.4s ease" }}>

        <img src={LOGO} style={{ width:180, display:"block", margin:"0 auto 6px" }} alt="Dona Luzia" />
        <div style={{ color:t.muted, fontSize:12, marginBottom:28, letterSpacing:0.5 }}>Sistema de Gestão</div>

        <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:24 }}>
          <div style={{ flex:1, height:1, background:t.bord }} />
          <div style={{ width:6,height:6,borderRadius:"50%",background:t.greenLight }} />
          <div style={{ flex:1, height:1, background:t.bord }} />
        </div>

        {/* Email */}
        <div style={{ textAlign:"left", marginBottom:14 }}>
          <label style={{ color:t.muted, fontSize:12, fontWeight:600, display:"block", marginBottom:6, letterSpacing:0.5, textTransform:"uppercase" }}>E-mail</label>
          <input
            type="email" value={email}
            onChange={e=>{setEmail(e.target.value);setErro(null);}}
            onKeyDown={e=>e.key==="Enter"&&handleLogin()}
            placeholder="seu@email.com"
            style={{ width:"100%", border:`1.5px solid ${t.bord}`, borderRadius:10, padding:"13px 14px", fontSize:14, color:t.text, background:"#fafaf8", transition:"all 0.2s" }}
          />
        </div>

        {/* Senha */}
        <div style={{ textAlign:"left", marginBottom:20 }}>
          <label style={{ color:t.muted, fontSize:12, fontWeight:600, display:"block", marginBottom:6, letterSpacing:0.5, textTransform:"uppercase" }}>Senha</label>
          <div style={{ position:"relative" }}>
            <input
              type={verSenha?"text":"password"} value={senha}
              onChange={e=>{setSenha(e.target.value);setErro(null);}}
              onKeyDown={e=>e.key==="Enter"&&handleLogin()}
              placeholder="••••••••"
              style={{ width:"100%", border:`1.5px solid ${t.bord}`, borderRadius:10, padding:"13px 44px 13px 14px", fontSize:14, color:t.text, background:"#fafaf8", transition:"all 0.2s" }}
            />
            <button onClick={()=>setVerSenha(!verSenha)} style={{ position:"absolute", right:12, top:"50%", transform:"translateY(-50%)", background:"none", border:"none", cursor:"pointer", fontSize:18, color:t.muted }}>
              {verSenha?"🙈":"👁"}
            </button>
          </div>
        </div>

        {/* Erro */}
        {erro && <div style={{ background:"#fef2f2", border:"1px solid #fecaca", borderRadius:8, padding:"10px 14px", color:t.red, fontSize:13, marginBottom:16, textAlign:"left" }}>⚠️ {erro}</div>}

        {/* Botão entrar */}
        <button
          onClick={handleLogin}
          disabled={entrando}
          style={{
            width:"100%", background:entrando?t.greenLight:`linear-gradient(135deg,${t.greenDark},${t.green})`,
            color:"#fff", border:"none", borderRadius:12,
            padding:"15px", fontSize:15, fontWeight:700,
            cursor:entrando?"not-allowed":"pointer",
            boxShadow:"0 4px 15px rgba(45,90,36,0.35)", transition:"all 0.2s",
            display:"flex", alignItems:"center", justifyContent:"center", gap:10,
          }}
        >
          {entrando
            ? <><div style={{ width:20,height:20,border:"2px solid rgba(255,255,255,0.4)",borderTop:"2px solid #fff",borderRadius:"50%",animation:"spin 0.8s linear infinite" }} />Entrando...</>
            : "🌿 Entrar no sistema"
          }
        </button>

        <div style={{ marginTop:24, color:t.muted, fontSize:12, lineHeight:1.7 }}>
          Acesso restrito a usuários autorizados.
        </div>

        <div style={{ marginTop:20, paddingTop:16, borderTop:`1px solid ${t.bord}`, color:t.muted, fontSize:11 }}>
          🌿 Dona Luzia Culinária Saudável
        </div>
      </div>
    </div>
  );
}
